  "routes[route-jjk-mahito-path].localizedName": "Le chemin de Mahito",
  "routes[route-jjk-mahito-path].description": "Le fléau né de la haine des humains les uns envers les autres : du cinéma de Kawasaki à Junpei, du vol des doigts de Sukuna à Shibuya, jusqu'à sa défaite face à Yuji.",
  "routes[route-jjk-mahito-path].steps[0].label": "Le cinéma de Kawasaki",
